   solid E          → SphereGeometry(1,120,80) remapped to the superellipsoid
                      |x/0.9|^6+|y/2.0|^6+|z/0.8|^6 = 1  (rounded box, NOT a blob),
                      MeshPhysicalMaterial #b3c6da, opacity .58, depthWrite false
   visible seams(9) → TubeGeometry(radius 0.015) #24537f   (real thickness)
   hidden seams (3) → Line + LineDashedMaterial #4b7fae, depthTest false
   normals N (7+2)  → Cylinder shaft + Cone head, #1f4e79, length 0.7, bold "N"
   field arrows (7) → Cylinder + Cone, #e8622a, length 1.35, lying IN the screen
                      plane of the printed view (no foreshortening); radial from
                      the centre of E in the "expanding field" mode
   pick patches (6) → PlaneGeometry remapped onto S, invisible until picked or
                      flux-shaded (green = outflow, red = inflow)
   labels           → x, y, z, E, S and one N per visible normal
   ─────────────────────────────────────────────────────────────────────────── */

const DEG = Math.PI / 180;

/* math (x,y,z) → world : math y is screen-right, math z is up, math x comes forward */
const M = (x, y, z) => new THREE.Vector3(y, z, x);

/* ── printed viewpoint, solved from the source figure's axis slopes ────── */
const PHX = 6, PHZ = 60;                       // screen slope of the y- and x-axes
const tX = Math.tan(PHX * DEG), tZ = Math.tan(PHZ * DEG);
const EL = Math.asin(Math.sqrt(tX * tZ));      // ≈ 25.26°
const AZ = Math.atan(Math.sqrt(tZ / tX));      // ≈ 76.15°
const CAM_RIGHT = new THREE.Vector3(Math.sin(AZ), 0, -Math.cos(AZ));
const CAM_UP = new THREE.Vector3(-Math.cos(AZ) * Math.sin(EL), Math.cos(EL), -Math.sin(AZ) * Math.sin(EL));

/* screen (right, up) → math (x,y,z) at a chosen depth; 1 unit ≈ 88 px of the source */
function fromScreen(sr, su, depth) {
  const y = (sr + Math.cos(AZ) * depth) / Math.sin(AZ);
  const z = (su + Math.cos(AZ) * Math.sin(EL) * y + Math.sin(AZ) * Math.sin(EL) * depth) / Math.cos(EL);
  return new THREE.Vector3(depth, y, z);
}

/* ── solid dimensions ──────────────────────────────────────────────────── */
const A = 0.9, B = 2.0, C = 0.8, NE = 6;       // half-extents (math x,y,z) + sharpness
const H = { x: A, y: B, z: C };
const OTH = { x: ['y', 'z'], y: ['x', 'z'], z: ['x', 'y'] };
const CENm = new THREE.Vector3(0, 1.7, 0.56);  // centre of E in math coords
const CEN = M(CENm.x, CENm.y, CENm.z);

const COL = {
  fill: 0xb3c6da, seam: 0x24537f, dash: 0x4b7fae,
  norm: 0x1f4e79, normHi: 0x0b3157, field: 0xe8622a, fieldHi: 0xff7a2f,
  axis: 0x111111, out: 0x2e9e4f, inn: 0xd0503f
};

/* uniform field: 50° above the horizontal, lying in the screen plane of the
   printed view so the arrows keep their full drawn length (no foreshortening) */
const FDIR = CAM_RIGHT.clone().multiplyScalar(Math.cos(50 * DEG))
  .addScaledVector(CAM_UP, Math.sin(50 * DEG)).normalize();

/* ── lights ────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.88));
const dl1 = new THREE.DirectionalLight(0xffffff, 0.5); dl1.position.set(3, 5, 4); scene.add(dl1);
const dl2 = new THREE.DirectionalLight(0xffffff, 0.28); dl2.position.set(-4, 2, -3); scene.add(dl2);

/* ── superellipsoid helpers (math-local coords, centred on CEN) ────────── */
const p6 = (v) => Math.pow(Math.abs(v), NE);
function surfVal(L) { return p6(L.x / A) + p6(L.y / B) + p6(L.z / C); }
function superT(dv) {
  const s = Math.pow(surfVal(dv), 1 / NE);
  return s > 1e-9 ? 1 / s : 0;
}
function normalWorld(L) {
  const g = new THREE.Vector3(
    Math.sign(L.x) * Math.pow(Math.abs(L.x), NE - 1) / Math.pow(A, NE),
    Math.sign(L.y) * Math.pow(Math.abs(L.y), NE - 1) / Math.pow(B, NE),
    Math.sign(L.z) * Math.pow(Math.abs(L.z), NE - 1) / Math.pow(C, NE));
  if (g.lengthSq() < 1e-12) g.set(0, 0, 1);
  return M(g.x, g.y, g.z).normalize();
}
const toWorld = (L) => M(L.x, L.y, L.z).add(CEN);
function surfAlong(dx, dy, dz) {
  const v = new THREE.Vector3(dx, dy, dz);
  return v.multiplyScalar(superT(v));
}
function capZ(lx, ly, sign) {
  const r = 1 - p6(lx / A) - p6(ly / B);
  return sign * C * Math.pow(Math.max(r, 0), 1 / NE);
}

/* ── the solid E ───────────────────────────────────────────────────────── */
const solidGeo = new THREE.SphereGeometry(1, 120, 80);
{
  const pa = solidGeo.attributes.position, na = solidGeo.attributes.normal;
  const u = new THREE.Vector3();
  for (let i = 0; i < pa.count; i++) {
    u.fromBufferAttribute(pa, i).normalize();
    const L = u.clone().multiplyScalar(superT(u));
    const w = toWorld(L.clone());
    pa.setXYZ(i, w.x, w.y, w.z);
    const nn = normalWorld(L);
    na.setXYZ(i, nn.x, nn.y, nn.z);
  }
  pa.needsUpdate = true; na.needsUpdate = true;
  solidGeo.computeBoundingBox(); solidGeo.computeBoundingSphere();
}
const solidMat = new THREE.MeshPhysicalMaterial({
  color: COL.fill, transparent: true, opacity: 0.58, depthWrite: false,
  side: THREE.DoubleSide, roughness: 0.6, metalness: 0.0, clearcoat: 0.25
});
const solid = new THREE.Mesh(solidGeo, solidMat);
solid.renderOrder = 1;
scene.add(solid);

/* ── 12 edge seams: 9 solid tubes, 3 dashed (hidden behind the body) ───── */
function seamPoints(along, fixed) {
  const pts = [];
  for (let i = 0; i <= 64; i++) {
    const t = -1 + 2 * i / 64;
    const L = new THREE.Vector3(fixed.x ?? 0, fixed.y ?? 0, fixed.z ?? 0);
    L[along] = t * H[along];
    pts.push(toWorld(L.multiplyScalar(superT(L))));
  }
  return pts;
}
const seamMats = [], dashMats = [];
for (const along of ['x', 'y', 'z']) {
  const [o1, o2] = OTH[along];
  for (const s1 of [-1, 1]) for (const s2 of [-1, 1]) {
    const fixed = {}; fixed[o1] = s1 * H[o1]; fixed[o2] = s2 * H[o2];
    const hidden =
      (along === 'z' && fixed.x < 0 && fixed.y < 0) ||
      (along === 'y' && fixed.x < 0 && fixed.z < 0) ||
      (along === 'x' && fixed.y < 0 && fixed.z < 0);
    const pts = seamPoints(along, fixed);
    if (hidden) {
      const g = new THREE.BufferGeometry().setFromPoints(pts);
      const m = new THREE.LineDashedMaterial({
        color: COL.dash, dashSize: 0.12, gapSize: 0.085,
        depthTest: false, transparent: true, opacity: 1
      });
      const l = new THREE.Line(g, m); l.computeLineDistances(); l.renderOrder = 5;
      scene.add(l); dashMats.push(m);
    } else {
      const curve = new THREE.CatmullRomCurve3(pts);
      const g = new THREE.TubeGeometry(curve, 90, 0.015, 8, false);
      const m = new THREE.MeshBasicMaterial({ color: COL.seam, transparent: true, opacity: 1 });
      const t = new THREE.Mesh(g, m); t.renderOrder = 3;
      scene.add(t); seamMats.push(m);
    }
  }
}

/* ── coordinate axes, clipped where they leave the solid (as in the source) ── */
function axis(tipMath) {
  const dm = new THREE.Vector3(tipMath[0], tipMath[1], tipMath[2]);
  const len = dm.length();
  const u = dm.clone().divideScalar(len);
  // bisect for the exit point of the surface along this ray from the origin
  let lo = 0, hi = len;
  for (let i = 0; i < 50; i++) {
    const mid = 0.5 * (lo + hi);
    const L = u.clone().multiplyScalar(mid).sub(CENm);
    if (surfVal(L) < 1) lo = mid; else hi = mid;
  }
  const start = M(u.x * hi, u.y * hi, u.z * hi);
  const tip = M(dm.x, dm.y, dm.z);
  const dirW = tip.clone().sub(start).normalize();
  const g = new THREE.BufferGeometry().setFromPoints([start, tip]);
  const line = new THREE.Line(g, new THREE.LineBasicMaterial({ color: COL.axis }));
  line.renderOrder = 4;
  scene.add(line);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.07, 0.22, 16),
    new THREE.MeshBasicMaterial({ color: COL.axis }));
  head.position.copy(tip);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dirW);
  head.renderOrder = 4;
  scene.add(head);
  return tip;
}
const tipZ = axis([0, 0, 2.5]);
const tipY = axis([0, 4.5, 0]);
const tipX = axis([2.9, 0, 0]);

/* ── arrow factory (cylinder shaft + cone head, re-settable) ───────────── */
function makeArrow(color, shaftR) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 14), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(shaftR * 2.8, 0.26, 18), mat);
  const g = new THREE.Group();
  g.add(shaft, head);
  g.renderOrder = 6; shaft.renderOrder = 6; head.renderOrder = 6;
  scene.add(g);
  const api = {
    group: g, mat, tip: new THREE.Vector3(), dir: new THREE.Vector3(0, 1, 0),
    set(origin, dir, len) {
      const dd = dir.clone().normalize();
      const headL = Math.min(0.3, len * 0.32);
      const sl = Math.max(0.02, len - headL);
      shaft.geometry.dispose(); shaft.geometry = new THREE.CylinderGeometry(shaftR, shaftR, sl, 14);
      shaft.position.y = sl / 2;
      head.geometry.dispose(); head.geometry = new THREE.ConeGeometry(shaftR * 2.8, headL, 18);
      head.position.y = sl + headL / 2;
      g.position.copy(origin);
      g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dd);
      api.dir.copy(dd);
      api.tip.copy(origin).addScaledVector(dd, len);
      return api;
    }
  };
  return api;
}

/* ── outward normals N ─────────────────────────────────────────────────── */
const NLEN = 0.7;
const normalSpecs = [
  { face: 'z+', L: new THREE.Vector3(-0.30, -0.60, capZ(-0.30, -0.60, 1)), d: [0, 0, 1], off: [11, -7], always: true },
  { face: 'z+', L: new THREE.Vector3(0.35, 0.35, capZ(0.35, 0.35, 1)), d: [0.30, 0.35, 0.90], off: [11, -7], always: true },
  { face: 'y-', L: surfAlong(0.20, -1, 0.00), d: [0, -1, 0], off: [-12, -10], always: true },
  { face: 'y+', L: surfAlong(0.00, 1, 0.40), d: [0, 1, 0], off: [10, -11], always: true },
  { face: 'y+', L: surfAlong(0.00, 1, -0.28), d: [0, 1, 0], off: [10, -11], always: true },
  { face: 'z-', L: new THREE.Vector3(-0.50, -0.60, capZ(-0.50, -0.60, -1)), d: [0, 0, -1], off: [-13, 7], always: true },
  { face: 'z-', L: new THREE.Vector3(0.50, 0.20, capZ(0.50, 0.20, -1)), d: [0, 0, -1], off: [12, 7], always: true },
  { face: 'x+', L: surfAlong(1, 0, 0.10), d: [1, 0, 0], off: [-12, 10], always: false },
  { face: 'x-', L: surfAlong(-1, 0, 0.10), d: [-1, 0, 0], off: [12, -9], always: false }
];
const normals = normalSpecs.map(sp => {
  const dirW = M(sp.d[0], sp.d[1], sp.d[2]).normalize();
  const a = makeArrow(COL.norm, 0.028);
  a.set(toWorld(sp.L.clone()), dirW, NLEN);
  const lbl = addLabel('<b>N</b>', a.tip.clone().addScaledVector(dirW, 0.08),
    { color: '#1f4e79', fontSize: '15px', offset: sp.off });
  return { arrow: a, mat: a.mat, group: a.group, face: sp.face, always: sp.always, label: lbl };
});

/* ── ambient field arrows (positions measured off the source figure) ───── */
const FLEN = 1.35;
//                      screen-right, screen-up, depth (math x)
const fieldScreen = [
  [0.93, 1.63, 0.6], [2.90, 1.82, -0.5], [0.42, -0.08, 1.4], [1.84, 0.03, 1.4],
  [3.30, 1.00, 0.0], [0.39, -0.92, 1.5], [2.44, -1.05, 1.5]
];
const fields = fieldScreen.map(s => {
  const m = fromScreen(s[0], s[1], s[2]);
  const centre = M(m.x, m.y, m.z);
  const a = makeArrow(COL.field, 0.038);
  return { arrow: a, mat: a.mat, centre, near: false };
});

/* ── clickable patches of S ────────────────────────────────────────────── */
function localFromUV(axisName, sign, u, v) {
  const [o1, o2] = OTH[axisName];
  const L = { x: 0, y: 0, z: 0 };
  L[o1] = u * H[o1] * 0.8;
  L[o2] = v * H[o2] * 0.8;
  const r = 1 - p6(L[o1] / H[o1]) - p6(L[o2] / H[o2]);
  L[axisName] = sign * H[axisName] * Math.pow(Math.max(r, 0), 1 / NE);
  return new THREE.Vector3(L.x, L.y, L.z);
}
const FACE_INFO = {
  'z+': { name: 'Top face', nm: '(0, 0, 1)' }, 'z-': { name: 'Bottom face', nm: '(0, 0, −1)' },
  'y+': { name: 'Right face', nm: '(0, 1, 0)' }, 'y-': { name: 'Left face', nm: '(0, −1, 0)' },
  'x+': { name: 'Front face', nm: '(1, 0, 0)' }, 'x-': { name: 'Back face', nm: '(−1, 0, 0)' }
};
const faces = [];
for (const axisName of ['x', 'y', 'z']) for (const sign of [1, -1]) {
  const key = axisName + (sign > 0 ? '+' : '-');
  const geo = new THREE.PlaneGeometry(2, 2, 20, 20);
  const pa = geo.attributes.position;
  for (let i = 0; i < pa.count; i++) {
    const L = localFromUV(axisName, sign, pa.getX(i), pa.getY(i));
    const nn = normalWorld(L);
    const w = toWorld(L.clone()).addScaledVector(nn, 0.025);
    pa.setXYZ(i, w.x, w.y, w.z);
  }
  pa.needsUpdate = true; geo.computeVertexNormals();
  geo.computeBoundingBox(); geo.computeBoundingSphere();
  const mat = new THREE.MeshBasicMaterial({
    color: 0x7fd4ff, transparent: true, opacity: 0, side: THREE.DoubleSide, depthWrite: false
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = 2;
  scene.add(mesh);
  const cL = localFromUV(axisName, sign, 0, 0);
  const rec = {
    key, mesh, mat, centre: toWorld(cL.clone()), n: normalWorld(cL), flux: 0,
    info: { title: FACE_INFO[key].name + ' of S', tooltip: FACE_INFO[key].name + ' — click for F·N', body: '' }
  };
  rec.info.onClick = () => selectFace(key);
  faces.push(rec);
  registerInteractive(mesh, rec.info);
}

/* ── numeric volume of E (used for the expanding-field total) ──────────── */
const VOL = (() => {
  const n = 44; let inside = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) for (let k = 0; k < n; k++) {
    const L = new THREE.Vector3(
      (-1 + 2 * (i + 0.5) / n) * A, (-1 + 2 * (j + 0.5) / n) * B, (-1 + 2 * (k + 0.5) / n) * C);
    if (surfVal(L) <= 1) inside++;
  }
  return 8 * A * B * C * inside / (n * n * n);
})();

/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: PHX, z: PHZ }, heightFraction: 0.88 });
controls.minZoom = 0.3; controls.maxZoom = 4;
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif';
addLabel(`<i style="${SER}">z</i>`, tipZ, { fontSize: '17px', offset: [-13, -4] });
addLabel(`<i style="${SER}">y</i>`, tipY, { fontSize: '17px', offset: [4, -14] });
addLabel(`<i style="${SER}">x</i>`, tipX, { fontSize: '17px', offset: [-15, 9] });
const eM = fromScreen(1.48, 0.45, -0.8);
const sM = fromScreen(3.47, 1.48, -0.9);
const lblE = addLabel(`<i style="${SER}">E</i>`, M(eM.x, eM.y, eM.z), { fontSize: '17px', color: '#10314f' });
const lblS = addLabel(`<i style="${SER}">S</i>`, M(sM.x, sM.y, sM.z), { fontSize: '17px', color: '#10314f' });

/* ── field model + state ───────────────────────────────────────────────── */
const state = { mode: 'uniform', sel: null, map: false };

function Fat(P) {                 // the vector field at a world point
  return state.mode === 'uniform' ? FDIR.clone() : P.clone().sub(CEN);
}
function updateField() {
  for (const a of fields) {
    let dir, len;
    if (state.mode === 'uniform') { dir = FDIR.clone(); len = FLEN; }
    else {
      dir = a.centre.clone().sub(CEN);
      const r = Math.max(dir.length(), 1e-6);
      dir.divideScalar(r);
      len = THREE.MathUtils.clamp(0.5 * r, 0.85, 1.7);
    }
    a.arrow.set(a.centre.clone().addScaledVector(dir, -len / 2), dir, len);
  }
}
function refreshFaceData() {
  for (const f of faces) {
    f.flux = Fat(f.centre).dot(f.n);
    const verb = f.flux > 0.05 ? 'leaves' : f.flux < -0.05 ? 'enters' : 'grazes';
    f.info.body =
      `Outward normal N ≈ ${FACE_INFO[f.key].nm}. ` +
      (state.mode === 'uniform'
        ? `For the uniform field, F·N ≈ ${f.flux.toFixed(2)} at every point of this patch, `
        : `For the expanding field F = r − r₀, F·N ≈ ${f.flux.toFixed(2)} at the centre of this patch, `) +
      `so the field ${verb} E here.`;
  }
}
const netBox = document.getElementById('netBox');
function refreshNet() {
  netBox.innerHTML = state.mode === 'uniform'
    ? '<b>F</b> is constant &rArr; div <b>F</b> = 0 everywhere.<br>' +
      '&#8750;<sub><i>S</i></sub> <b>F</b>&middot;<b>N</b> <i>dS</i> = <b>0</b> &nbsp;=&nbsp; ' +
      '&#8747;&#8747;&#8747;<sub><i>E</i></sub> 0 <i>dV</i>. Every bit that flows in one side flows out the other.'
    : '<b>F</b> = <b>r</b> &minus; <b>r</b><sub>0</sub> &rArr; div <b>F</b> = 3 everywhere.<br>' +
      '&#8750;<sub><i>S</i></sub> <b>F</b>&middot;<b>N</b> <i>dS</i> = 3&middot;Vol(<i>E</i>) &asymp; ' +
      (3 * VOL).toFixed(1) + ' &nbsp;=&nbsp; &#8747;&#8747;&#8747;<sub><i>E</i></sub> 3 <i>dV</i>.';
}

function applyStyles() {
  for (const f of faces) {
    const sel = state.sel === f.key;
    if (sel) { f.mat.color.set(f.flux >= 0 ? COL.out : COL.inn); f.mat.opacity = 0.55; }
    else if (state.map) { f.mat.color.set(f.flux >= 0 ? COL.out : COL.inn); f.mat.opacity = 0.3; }
    else f.mat.opacity = 0;
  }
  for (const n of normals) {
    const show = n.always || n.face === state.sel;
    let op = 1, col = COL.norm;
    if (state.sel) { if (n.face === state.sel) { op = 1; col = COL.normHi; } else op = 0.3; }
    n.mat.color.set(col);
    n.mat.opacity = op;
    n.group.visible = show;
    n.label.div.style.visibility = show ? 'visible' : 'hidden';
    n.label.div.style.opacity = String(op);
  }
  for (const a of fields) {
    let op = 1, col = COL.field;
    if (state.sel) { op = a.near ? 1 : 0.28; col = a.near ? COL.fieldHi : COL.field; }
    a.mat.color.set(col);
    a.mat.opacity = op;
  }
  document.getElementById('btnUniform').classList.toggle('active', state.mode === 'uniform');
  document.getElementById('btnSource').classList.toggle('active', state.mode === 'source');
  document.getElementById('chkMap').checked = state.map;
  document.querySelectorAll('#ui button[data-face]').forEach(b =>
    b.classList.toggle('active', b.dataset.face === state.sel));
}

/* ── selection ─────────────────────────────────────────────────────────── */
const readout = document.getElementById('readout');
function selectFace(key) {
  state.sel = key;
  const f = faces.find(x => x.key === key);
  const order = fields.map((a, i) => ({ i, dd: a.centre.distanceTo(f.centre) })).sort((p, q) => p.dd - q.dd);
  fields.forEach(a => a.near = false);
  order.slice(0, 3).forEach(o => fields[o.i].near = true);
  const v = f.flux;
  const verdict = v > 0.05
    ? '<b style="color:#1a7f37">positive</b> &mdash; the field <b>exits</b> E here'
    : v < -0.05
      ? '<b style="color:#c0392b">negative</b> &mdash; the field <b>enters</b> E here'
      : '<b>&asymp; 0</b> &mdash; the field grazes this patch';
  readout.innerHTML =
    `<b>${FACE_INFO[key].name}</b><br>outward <b>N</b> = ${FACE_INFO[key].nm}<br>` +
    `<b>F</b>&middot;<b>N</b> = ${v.toFixed(2)} &rarr; ${verdict}.`;
  applyStyles();
}
function clearSelection() {
  state.sel = null;
  fields.forEach(a => a.near = false);
  readout.innerHTML = 'No patch selected.';
  applyStyles();
  hidePopup();
}
function setMode(m) {
  state.mode = m;
  updateField();
  refreshFaceData();
  refreshNet();
  if (state.sel) selectFace(state.sel); else applyStyles();
}

/* ── UI wiring ─────────────────────────────────────────────────────────── */
document.getElementById('btnUniform').addEventListener('click', () => setMode('uniform'));
document.getElementById('btnSource').addEventListener('click', () => setMode('source'));
document.getElementById('chkMap').addEventListener('change', (e) => { state.map = e.target.checked; applyStyles(); });
document.querySelectorAll('#ui button[data-face]').forEach(b =>
  b.addEventListener('click', () => selectFace(b.dataset.face)));
document.getElementById('btnClear').addEventListener('click', clearSelection);

/* ── guided steps ──────────────────────────────────────────────────────── */
const STEPS = [
  {
    t: 'The closed surface S bounding E',
    n: 'The pale blue solid E is enclosed by the closed surface S. The short dark-blue arrows N are unit normals: on every patch of S they point away from the interior. Dashed curves are the three hidden edges.',
    run() { state.mode = 'uniform'; state.map = false; setMode('uniform'); clearSelection(); }
  },
