const FLEN = 1.35;
//                      screen-right, screen-up, depth (math x)
const fieldScreen = [
  [0.93, 1.63, 0.6], [2.90, 1.82, -0.5], [0.42, -0.08, 1.4], [1.84, 0.03, 1.4],
  [3.30, 1.00, 0.0], [0.39, -0.92, 1.5], [2.44, -1.05, 1.5]
