const FACE_INFO = {
  'z+': { name: 'Top face', nm: '(0, 0, 1)' }, 'z-': { name: 'Bottom face', nm: '(0, 0, −1)' },
  'y+': { name: 'Right face', nm: '(0, 1, 0)' }, 'y-': { name: 'Left face', nm: '(0, −1, 0)' },
  'x+': { name: 'Front face', nm: '(1, 0, 0)' }, 'x-': { name: 'Back face', nm: '(−1, 0, 0)' }
