const faces = [];
for (const axisName of ['x', 'y', 'z']) for (const sign of [1, -1]) {
  const key = axisName + (sign > 0 ? '+' : '-');
  const geo = new THREE.PlaneGeometry(2, 2, 20, 20);
  const pa = geo.attributes.position;
  for (let i = 0; i < pa.count; i++) {
    const L = localFromUV(axisName, sign, pa.getX(i), pa.getY(i));
    const nn = normalWorld(L);
