  const cL = localFromUV(axisName, sign, 0, 0);
  const rec = {
    key, mesh, mat, centre: toWorld(cL.clone()), n: normalWorld(cL), flux: 0,
    info: { title: FACE_INFO[key].name + ' of S', tooltip: FACE_INFO[key].name + ' — click for F·N', body: '' }
  };
  rec.info.onClick = () => selectFace(key);
  faces.push(rec);
  registerInteractive(mesh, rec.info);
}

/* ── numeric volume of E (used for the expanding-field total) ──────────── */
const VOL = (() => {
  const n = 44; let inside = 0;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) for (let k = 0; k < n; k++) {
