/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: PHX, z: PHZ }, heightFraction: 0.88 });
controls.minZoom = 0.3; controls.maxZoom = 4;
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif';
addLabel(`<i style="${SER}">z</i>`, tipZ, { fontSize: '17px', offset: [-13, -4] });
addLabel(`<i style="${SER}">y</i>`, tipY, { fontSize: '17px', offset: [4, -14] });
addLabel(`<i style="${SER}">x</i>`, tipX, { fontSize: '17px', offset: [-15, 9] });
const eM = fromScreen(1.48, 0.45, -0.8);
const sM = fromScreen(3.47, 1.48, -0.9);
const lblE = addLabel(`<i style="${SER}">E</i>`, M(eM.x, eM.y, eM.z), { fontSize: '17px', color: '#10314f' });
