/* ── arrow factory (cylinder shaft + cone head, re-settable) ───────────── */
function makeArrow(color, shaftR) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, 1, 14), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(shaftR * 2.8, 0.26, 18), mat);
  const g = new THREE.Group();
  g.add(shaft, head);
  g.renderOrder = 6; shaft.renderOrder = 6; head.renderOrder = 6;
  scene.add(g);
  const api = {
    group: g, mat, tip: new THREE.Vector3(), dir: new THREE.Vector3(0, 1, 0),
    set(origin, dir, len) {
      const dd = dir.clone().normalize();
      const headL = Math.min(0.3, len * 0.32);
      const sl = Math.max(0.02, len - headL);
      shaft.geometry.dispose(); shaft.geometry = new THREE.CylinderGeometry(shaftR, shaftR, sl, 14);
      shaft.position.y = sl / 2;
      head.geometry.dispose(); head.geometry = new THREE.ConeGeometry(shaftR * 2.8, headL, 18);
      head.position.y = sl + headL / 2;
      g.position.copy(origin);
      g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dd);
      api.dir.copy(dd);
      api.tip.copy(origin).addScaledVector(dd, len);
      return api;
    }
  };
  return api;
}

