/* ── clickable patches of S ────────────────────────────────────────────── */
function localFromUV(axisName, sign, u, v) {
  const [o1, o2] = OTH[axisName];
  const L = { x: 0, y: 0, z: 0 };
  L[o1] = u * H[o1] * 0.8;
  L[o2] = v * H[o2] * 0.8;
  const r = 1 - p6(L[o1] / H[o1]) - p6(L[o2] / H[o2]);
  L[axisName] = sign * H[axisName] * Math.pow(Math.max(r, 0), 1 / NE);
  return new THREE.Vector3(L.x, L.y, L.z);
}
